# ====================================================
# misc_params.map – high-risk query-string parameters
# Last updated: 2025-12-30 – maintainer: <your-name>
# ====================================================

# Parameters commonly abused for remote command execution / logic tampering
"(?i)(?:^|&)(?:cmd|exec)=.*"          1;  # Command or exec injection
"(?i)(?:^|&)action=.*"               1;  # Sensitive action parameter【5-0-0】

# Parameters exposing credentials or tokens
"(?i)(?:^|&)(?:otp)=.*"               1;  # One-time password in URL【5-0-3】
